* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  margin: 0;
  padding: 0;
  overflow: hidden !important;
  width: 100%;
  height: 100%;
  background: transparent;
}

.stage-header-container {
  box-sizing: border-box;
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 16px 24px;
  background: #ffffff;
  border-radius: 8px;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.stage-header-left {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stage-breadcrumb-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stage-phase-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #2563eb;
  text-transform: uppercase;
  line-height: 1.2;
}

.stage-title {
  margin: 0;
  font-size: 28px;
  font-weight: 800;
  color: #0f172a;
  line-height: 1.25;
  letter-spacing: -0.3px;
}

.stage-subtitle {
  margin: 0;
  font-size: 13px;
  font-weight: 400;
  color: #64748b;
  line-height: 1.5;
}

.stage-header-right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
  padding-top: 4px;
}

.refresh-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 6px 16px;
  border-radius: 8px;
  border: 1.5px solid #cbd5e1;
  font-size: 13px;
  font-weight: 600;
  background-color: #ffffff;
  color: #475569;
  white-space: nowrap;
  cursor: pointer;
  height: 40px;
  transition: all 0.15s ease;
  font-family: inherit;
}

.refresh-btn:hover {
  background-color: #f8fafc;
  border-color: #94a3b8;
  color: #0f172a;
}

.refresh-btn:active {
  background-color: #f1f5f9;
  transform: scale(0.98);
}

.conversation-history-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 6px 20px;
  border-radius: 8px;
  border: 1.5px solid #2563eb;
  font-size: 14px;
  font-weight: 600;
  background-color: #ffffff;
  color: #2563eb;
  white-space: nowrap;
  cursor: pointer;
  height: 40px;
  transition: all 0.15s ease;
  font-family: inherit;
}

.conversation-history-btn:hover {
  background-color: #eff6ff;
  border-color: #1d4ed8;
  color: #1d4ed8;
}

.conversation-history-btn:active {
  background-color: #dbeafe;
}

.stage-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  border-radius: 9999px;
  height: 40px;
  font-size: 13px;
  font-weight: 700;
  background-color: #e0e7ff;
  color: #2563eb;
  white-space: nowrap;
  box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

.stage-status-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: currentColor;
  flex-shrink: 0;
}

